import{_ as o,o as a,c,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Miscellaneous-Functions.md","filePath":"manual-zh/Miscellaneous-Functions.md","lastUpdated":1785684581000}'),t={name:"manual-zh/Miscellaneous-Functions.md"};function d(s,e,r,i,p,l){return a(),c("div",null,[...e[0]||(e[0]=[n('<h4 id="_7-7-9-杂项函数" tabindex="-1">7.7.9 杂项函数 <a class="header-anchor" href="#_7-7-9-杂项函数" aria-label="Permalink to &quot;7.7.9 杂项函数&quot;">​</a></h4><p>Function: __<strong>LAG</strong> <em>( variable[, n])</em></p><p>variable 必须是数值型或字符串型变量名。<code>LAG</code> 产生当前个案之前第 n 个个案中该变量的值。对于前 n 个个案，结果为系统缺失值（数值型变量）或空白（字符串型变量）。</p><p><code>LAG</code> 从过程执行后成为新活动数据集的个案中获取值。因此，<code>LAG</code> 不会返回被 <code>SELECT IF</code> 等变换丢弃的个案中的值，并且像 <code>COMPUTE</code> 这样修改数据的变换会改变 <code>LAG</code> 返回的值。无论这些变换在 <code>LAG</code> 使用之前还是之后，这两种情况都成立。</p><p>如果 <code>LAG</code> 在 <code>TEMPORARY</code> 之前使用，则它返回的值是 <code>TEMPORARY</code> 之前紧邻的个案中的值。<code>LAG</code> 不能在 <code>TEMPORARY</code> 之后使用。</p><p>如果省略，ncases 默认为 1。否则，ncases 必须是一个较小的正整数常量。没有明确的限制，但使用较大的值会增加内存消耗。</p><p>Function: __<strong>YRMODA</strong> <em>( year, month, day)</em></p><p>year 为年份，介于 0 和 99 之间，或至少为 1582。与其他 PSPP 日期函数不同，0 到 99 之间的年份始终对应于 1900 到 1999。month 为 1 到 13 之间的月份。day 为 0 到 31 之间的日期。日期为 0 表示上个月的最后一天，月份为 13 表示下一年的第一个月。year 必须在范围内。year、month 和 day 都必须为整数。</p><p><code>YRMODA</code> 的结果为 1582 年 10 月 15 日与指定日期之间的天数，再加一。传递给 <code>YRMODA</code> 的日期必须在 1582 年 10 月 15 日或之后。1582 年 10 月 15 日的值为 1。</p><p>Function: <em>VALUELABEL</em> <strong>( variable)</strong></p><p>返回与 variable 当前值关联的值标签所对应的字符串。如果 variable 的当前值没有关联标签，则该函数返回空字符串。variable 可以是数值型或字符串型变量。</p>',11)])])}const u=o(t,[["render",d]]);export{m as __pageData,u as default};
